T=D['table']; c=lambda r:f"{r['auroc']:.3f} [{r['ci95'][0]:.3f}, {r['ci95'][1]:.3f}]"; ci=lambda x:f"[{x[0]:+.3f}, {x[1]:+.3f}]"
HL1,SL1,OL1,HTM,STM='Haiku L1 (phase 2, 3 runs)','Sonnet L1 (3 runs)','Opus L1 (1 run)','Haiku task-match (3 runs)','Sonnet task-match (3 runs)'
